INSERT INTO "events" VALUES(161,2,'vlad','BelarusLord-chat','submit','Схема v1 (core/src/commonMain/kotlin/org/easypaper/model/Schema.kt: CareRequest, 7 WidgetSpec, Entry + 7 EntryPayload, PatientRecord, EasyPaperJson) + шифрованное хранилище (storage/RecordStore.kt: AES-256-GCM через dev.whyoleg.cryptography 0.6.0, id записи как associated data, интерфейс BlobStore, generateRecordKey). Зависимости добавлены в libs.versions.toml и core/build.gradle.kts (serialization plugin, serialization-json 1.9.0, cryptography core+provider-optimal, coroutines-test). Ветка на базе каркаса 616b398. Тесты: 11 в core/src/commonTest — :core:jvmTest 11/11 зелёные на Linux; :core:compileTestKotlinWasmJs и :core:compileTestKotlinJs компилируются. python test.py на моём ноутбуке не запускается из-за отсутствия Android SDK (см. ревью #1). Не сделано (вне критерия): платформенные BlobStore (файл/localStorage) и хранение ключа — удобнее делать вместе с UI #4.','{"branch":"attempt/vlad/task-2-2","sha":"4610fac45908b23aa747ce5838f777947e3375d3","task_id":2,"text":"Схема v1 (core/src/commonMain/kotlin/org/easypaper/model/Schema.kt: CareRequest, 7 WidgetSpec, Entry + 7 EntryPayload, PatientRecord, EasyPaperJson) + шифрованное хранилище (storage/RecordStore.kt: AES-256-GCM через dev.whyoleg.cryptography 0.6.0, id записи как associated data, интерфейс BlobStore, generateRecordKey). Зависимости добавлены в libs.versions.toml и core/build.gradle.kts (serialization plugin, serialization-json 1.9.0, cryptography core+provider-optimal, coroutines-test). Ветка на базе каркаса 616b398. Тесты: 11 в core/src/commonTest — :core:jvmTest 11/11 зелёные на Linux; :core:compileTestKotlinWasmJs и :core:compileTestKotlinJs компилируются. python test.py на моём ноутбуке не запускается из-за отсутствия Android SDK (см. ревью #1). Не сделано (вне критерия): платформенные BlobStore (файл/localStorage) и хранение ключа — удобнее делать вместе с UI #4."}','2026-11-21T15:21:54+00:00');
INSERT INTO "events" VALUES(162,9,'vlad','BelarusLord-chat','start','формат отчёта + шифрование + QR-строка в core','{"task_id":9,"text":"формат отчёта + шифрование + QR-строка в core"}','2026-11-21T15:22:40+00:00');
INSERT INTO "events" VALUES(163,9,'vlad','BelarusLord-chat','plan','ЧТО (core, пакет org.easypaper.report, без новых зависимостей). ФОРМАТ (первый коммит, сразу deliver — нужен #10 Павла и #7/#8 Михаила): Report{schemaVersion=1, id, createdAt(epoch ms), record: PatientRecord, summary: String? (заполняет ИИ #7, со ссылками entryId), fhir: JsonObject (FHIR-подобный Bundle)}. FHIR: PatientRecord.toFhirBundle() — Bundle(collection): давление -> Observation LOINC 85354-9 (8480-6 sys, 8462-4 dia, 8867-4 pulse), вода -> Observation, лекарства -> MedicationStatement (код GTIN, source, confirmed), опросник -> QuestionnaireResponse, дневник/еда/вопросы -> Observation с valueString; у каждого ресурса id = entryId (ссылки сводки на оригиналы). ПЕРЕДАЧА: sealReport(report) -> SealedReport(bytes, key) — AES-256-GCM, новый случайный ключ на каждый отчёт, reportId как associated data; QR-строка ''ep1:<reportId>:<base64url key>'' (+ опц. адрес загрузки, когда будет #8); openReport(bytes, qr) -> Report. Шифрованные байты уходят через сервер #8 или файл, ключ — только в QR. ТЕСТЫ commonTest: round-trip Report JSON; без ключа/чужой ключ/порча -> ошибка (критерий); QR парсится туда-обратно, мусор -> ошибка; FHIR-бандл содержит нужные LOINC и id записей. РИСКИ: размер QR — в нём только ключ+id, не данные; сам QR-рисунок (картинка) — в UI #10.','{"task_id":9,"text":"ЧТО (core, пакет org.easypaper.report, без новых зависимостей). ФОРМАТ (первый коммит, сразу deliver — нужен #10 Павла и #7/#8 Михаила): Report{schemaVersion=1, id, createdAt(epoch ms), record: PatientRecord, summary: String? (заполняет ИИ #7, со ссылками entryId), fhir: JsonObject (FHIR-подобный Bundle)}. FHIR: PatientRecord.toFhirBundle() — Bundle(collection): давление -> Observation LOINC 85354-9 (8480-6 sys, 8462-4 dia, 8867-4 pulse), вода -> Observation, лекарства -> MedicationStatement (код GTIN, source, confirmed), опросник -> QuestionnaireResponse, дневник/еда/вопросы -> Observation с valueString; у каждого ресурса id = entryId (ссылки сводки на оригиналы). ПЕРЕДАЧА: sealReport(report) -> SealedReport(bytes, key) — AES-256-GCM, новый случайный ключ на каждый отчёт, reportId как associated data; QR-строка ''ep1:<reportId>:<base64url key>'' (+ опц. адрес загрузки, когда будет #8); openReport(bytes, qr) -> Report. Шифрованные байты уходят через сервер #8 или файл, ключ — только в QR. ТЕСТЫ commonTest: round-trip Report JSON; без ключа/чужой ключ/порча -> ошибка (критерий); QR парсится туда-обратно, мусор -> ошибка; FHIR-бандл содержит нужные LOINC и id записей. РИСКИ: размер QR — в нём только ключ+id, не данные; сам QR-рисунок (картинка) — в UI #10."}','2026-11-21T15:22:40+00:00');
