INSERT INTO "events" VALUES(168,9,'vlad','BelarusLord-chat','submit','Формат отчёта v1 + передача (core, org.easypaper.report). Report{schemaVersion, id, createdAt, record, summary (ИИ #7 ссылается на [entryId]), fhir}. PatientRecord.toFhirBundle(): Bundle collection; давление -> Observation LOINC 85354-9/8480-6/8462-4/8867-4, вода/еда/дневник/вопросы -> Observation, лекарства -> MedicationStatement (GTIN, draft пока не подтверждено), опросник -> QuestionnaireResponse; id ресурса = entryId. sealReport(): новый AES-256-GCM ключ на отчёт, reportId как associated data; QR-строка ep1:<id>:<base64url key>; reportIdFromQr(), openReport(bytes, qr). AES-GCM вынесен в storage.aesGcm (RecordStore использует его же). Тесты core/src/commonTest/.../report/ReportTest.kt (4): JSON round-trip; открывается только своим QR — чужой ключ и порча байт -> ошибка, в байтах нет открытого текста; мусорные QR отклоняются; FHIR — id записей, типы ресурсов, LOINC, draft. :core:jvmTest 15/15 зелёные (Linux), wasmJs/js компилируются. python test.py не запускал: на моём ноутбуке нет Android SDK. Вне задачи: картинка QR и экран — #10, загрузка байтов на сервер — #8.','{"branch":"attempt/vlad/task-9-1","sha":"ad5879b230ebcc719aa0b632c2b15ca507195bab","task_id":9,"text":"Формат отчёта v1 + передача (core, org.easypaper.report). Report{schemaVersion, id, createdAt, record, summary (ИИ #7 ссылается на [entryId]), fhir}. PatientRecord.toFhirBundle(): Bundle collection; давление -> Observation LOINC 85354-9/8480-6/8462-4/8867-4, вода/еда/дневник/вопросы -> Observation, лекарства -> MedicationStatement (GTIN, draft пока не подтверждено), опросник -> QuestionnaireResponse; id ресурса = entryId. sealReport(): новый AES-256-GCM ключ на отчёт, reportId как associated data; QR-строка ep1:<id>:<base64url key>; reportIdFromQr(), openReport(bytes, qr). AES-GCM вынесен в storage.aesGcm (RecordStore использует его же). Тесты core/src/commonTest/.../report/ReportTest.kt (4): JSON round-trip; открывается только своим QR — чужой ключ и порча байт -> ошибка, в байтах нет открытого текста; мусорные QR отклоняются; FHIR — id записей, типы ресурсов, LOINC, draft. :core:jvmTest 15/15 зелёные (Linux), wasmJs/js компилируются. python test.py не запускал: на моём ноутбуке нет Android SDK. Вне задачи: картинка QR и экран — #10, загрузка байтов на сервер — #8."}','2026-11-21T15:24:02+00:00');
