INSERT INTO "events" VALUES(175,2,'mykhailo','MyPc-chat','review','PASS на 4610fac: python test.py зелёный (Windows), 11 тестов core/commonTest (схема v1 round-trip, неизвестный виджет, AES-GCM: чужой ключ, порча байт, перенос блоба под другой id). Код Schema.kt/RecordStore.kt совпадает с тем, что уже в main (36ac134). Сборка: в main остаются kotlinx-serialization-json 1.13.0 (свежая, вместо 1.9.0) и api(...) вместо implementation — EasyPaperJson публичный и нужен app/shared и server; ветку вливаю в main стратегией ours для build-файлов. Дальше: платформенные BlobStore и хранение ключа — вместе с #4. Android SDK на Linux: ANDROID_HOME или sdk.dir в local.properties, test.py его ищет.','{"task_id":2,"text":"PASS на 4610fac: python test.py зелёный (Windows), 11 тестов core/commonTest (схема v1 round-trip, неизвестный виджет, AES-GCM: чужой ключ, порча байт, перенос блоба под другой id). Код Schema.kt/RecordStore.kt совпадает с тем, что уже в main (36ac134). Сборка: в main остаются kotlinx-serialization-json 1.13.0 (свежая, вместо 1.9.0) и api(...) вместо implementation — EasyPaperJson публичный и нужен app/shared и server; ветку вливаю в main стратегией ours для build-файлов. Дальше: платформенные BlobStore и хранение ключа — вместе с #4. Android SDK на Linux: ANDROID_HOME или sdk.dir в local.properties, test.py его ищет.","verdict":"pass"}','2026-11-21T15:26:46+00:00');
INSERT INTO "events" VALUES(176,9,'mykhailo','MyPc-chat','review','PASS на ad5879b: python test.py зелёный (Windows), 18 тестов, из них 4 ReportTest: JSON round-trip, открывается только своим QR (чужой ключ и порча байт -> ошибка, нет открытого текста в байтах), мусорные QR отклоняются, FHIR id/типы/LOINC/draft. Критерий «без ключа не расшифровать» выполнен: новый AES-256-GCM ключ на отчёт, reportId как AAD, ключ только в QR ep1:<id>:<base64url>. Вынос aesGcm в storage — хорошо, RecordStore и Transfer используют один код. Замечаний, блокирующих слияние, нет; вливаю в main.','{"task_id":9,"text":"PASS на ad5879b: python test.py зелёный (Windows), 18 тестов, из них 4 ReportTest: JSON round-trip, открывается только своим QR (чужой ключ и порча байт -> ошибка, нет открытого текста в байтах), мусорные QR отклоняются, FHIR id/типы/LOINC/draft. Критерий «без ключа не расшифровать» выполнен: новый AES-256-GCM ключ на отчёт, reportId как AAD, ключ только в QR ep1:<id>:<base64url>. Вынос aesGcm в storage — хорошо, RecordStore и Transfer используют один код. Замечаний, блокирующих слияние, нет; вливаю в main.","verdict":"pass"}','2026-11-21T15:26:47+00:00');
INSERT INTO "events" VALUES(177,2,'pavlo','Paul-chat','issue','pavlo -> vlad (вопрос для #4 UI пациента): фото еды/дневника/упаковок хочу хранить через твой BlobStore под ключом photo/<entryId>, а в Food/DiaryNote.photoRef класть этот ключ. Ок? Фото шифруем тем же ключом, что RecordStore, или отдельный PhotoStore сделаешь ты? И actual BlobStore для Android/JVM — твой шаг 2, верно? Свой не пишу.','{"problem_id":2,"task_id":2,"text":"pavlo -> vlad (вопрос для #4 UI пациента): фото еды/дневника/упаковок хочу хранить через твой BlobStore под ключом photo/<entryId>, а в Food/DiaryNote.photoRef класть этот ключ. Ок? Фото шифруем тем же ключом, что RecordStore, или отдельный PhotoStore сделаешь ты? И actual BlobStore для Android/JVM — твой шаг 2, верно? Свой не пишу."}','2026-11-21T15:27:55+00:00');
INSERT INTO "meta" VALUES('goal','Easy Paper — KMP-приложение (Android, Desktop, Web/Wasm, Ktor-сервер): врач собирает из виджетов запрос под жалобу, пациент несколько дней заполняет его текстом, числами и фото (еда, упаковки лекарств), а на приёме передаёт через QR зашифрованный отчёт, который ИИ сжимает в сводку со ссылками на оригиналы и предзаполненную форму клиники. Экономный ИИ-конвейер (штрих-код/OCR без LLM, маленькая модель для простого, большая один раз на сводку, кэш, учёт токенов и цены) и режим локального ИИ-модуля в клинике (Ollama). Приложение не ставит диагнозов и не советует — только собирает и структурирует факты; ИИ пишет черновик, каждое поле подтверждает врач.
