INSERT INTO "problems" VALUES(1,1,'pavlo','pavlo: каркас 616b398 (Task 1: KMP skeleton...) уже в GitHub origin/main и attempt/mykhailo/task-1-1, но на хабе main = пустой 824112f, а задача 1 всё ещё ''в работе''. Сделай, пожалуйста, team deliver attempt/mykhailo/task-1-1 и team submit 1 --sha 616b398c1dbd3b80d75aca5d95d9336cbac2ac12 --branch attempt/mykhailo/task-1-1 - я готов сразу сделать ревью (test.py, Desktop, Android). Заодно: main на хабе и в origin разошлись - какой считаем базой?','open',NULL,NULL,'2026-11-21T15:17:19+00:00',NULL);
INSERT INTO "problems" VALUES(2,2,'pavlo','pavlo -> vlad (вопрос для #4 UI пациента): фото еды/дневника/упаковок хочу хранить через твой BlobStore под ключом photo/<entryId>, а в Food/DiaryNote.photoRef класть этот ключ. Ок? Фото шифруем тем же ключом, что RecordStore, или отдельный PhotoStore сделаешь ты? И actual BlobStore для Android/JVM — твой шаг 2, верно? Свой не пишу.','open',NULL,NULL,'2026-11-21T15:27:55+00:00',NULL);
INSERT INTO "requests" VALUES('bec2a0f2-4aee-58bf-a6c3-4c7f6bef40e4','5f3c9405d3c65202600702f0fd76f4d517321a0ca1fda13cc4e9f2f1e03d2cdc',200,'{"event_id":1,"goal":"Easy Paper — KMP-приложение (Android, Desktop, Web/Wasm, Ktor-сервер): врач собирает из виджетов запрос под жалобу, пациент несколько дней заполняет его текстом, числами и фото (еда, упаковки лекарств), а на приёме передаёт через QR зашифрованный отчёт, который ИИ сжимает в сводку со ссылками на оригиналы и предзаполненную форму клиники. Экономный ИИ-конвейер (штрих-код/OCR без LLM, маленькая модель для простого, большая один раз на сводку, кэш, учёт токенов и цены) и режим локального ИИ-модуля в клинике (Ollama). Приложение не ставит диагнозов и не советует — только собирает и структурирует факты; ИИ пишет черновик, каждое поле подтверждает врач.\nПорядок: задача 1 первая; UI-задачи 4, 5, 10 — только после утверждённого mykhailo docs/design.md (задача 3). Секреты только в env/локально; коммиты без подписи Claude; в origin не пушить."}','2026-11-21T14:45:12+00:00');
