INSERT INTO "requests" VALUES('7f7b72d0-4305-43b0-82fa-9eacfd5066df','299e2f51aa9dd328101612168f2e70a67857e5b53b353437bbf0b29e8ff5c59f',200,'{"event_id":163,"task":{"assignee":"vlad","author":"mykhailo","branch":null,"builds":0,"checkpoint_sha":null,"client":"BelarusLord-chat","created":"2026-11-21T14:45:14+00:00","criteria":"без ключа не расшифровать","id":9,"lease_expires":1795274740.3562646,"lease_id":"4125c722-0f65-433b-9eda-4464360b1675","owner":"vlad","phase":"build","plan":"ЧТО (core, пакет org.easypaper.report, без новых зависимостей). ФОРМАТ (первый коммит, сразу deliver — нужен #10 Павла и #7/#8 Михаила): Report{schemaVersion=1, id, createdAt(epoch ms), record: PatientRecord, summary: String? (заполняет ИИ #7, со ссылками entryId), fhir: JsonObject (FHIR-подобный Bundle)}. FHIR: PatientRecord.toFhirBundle() — Bundle(collection): давление -> Observation LOINC 85354-9 (8480-6 sys, 8462-4 dia, 8867-4 pulse), вода -> Observation, лекарства -> MedicationStatement (код GTIN, source, confirmed), опросник -> QuestionnaireResponse, дневник/еда/вопросы -> Observation с valueString; у каждого ресурса id = entryId (ссылки сводки на оригиналы). ПЕРЕДАЧА: sealReport(report) -> SealedReport(bytes, key) — AES-256-GCM, новый случайный ключ на каждый отчёт, reportId как associated data; QR-строка ''ep1:<reportId>:<base64url key>'' (+ опц. адрес загрузки, когда будет #8); openReport(bytes, qr) -> Report. Шифрованные байты уходят через сервер #8 или файл, ключ — только в QR. ТЕСТЫ commonTest: round-trip Report JSON; без ключа/чужой ключ/порча -> ошибка (критерий); QR парсится туда-обратно, мусор -> ошибка; FHIR-бандл содержит нужные LOINC и id записей. РИСКИ: размер QR — в нём только ключ+id, не данные; сам QR-рисунок (картинка) — в UI #10.","review_notes":null,"status":"running","submitter":null,"title":"Отчёт и передача: сводка + FHIR-подобный JSON, шифрование, QR с ключом; формат отчёта зафиксировать первым коммитом [IMC][JB]","updated":"2026-11-21T15:22:40+00:00"}}','2026-11-21T15:22:40+00:00');
