INSERT INTO "requests" VALUES('beb255f1-8674-4738-b582-f33a3faad776','74dcf1d3247e7df603c4b82f0eda66a7446f97cf157a8975c51ea060c8246fe3',200,'{"event_id":169,"task":{"assignee":"vlad","author":"mykhailo","branch":"attempt/vlad/task-2-2","builds":1,"checkpoint_sha":"4610fac45908b23aa747ce5838f777947e3375d3","client":"MyPc-chat","created":"2026-11-21T14:45:13+00:00","criteria":"тесты commonTest","id":2,"lease_expires":1795274907.9936903,"lease_id":"35cfa7b0-a38c-42ab-9037-3a38e6ceee25","owner":"mykhailo","phase":"review","plan":"ПОПРАВКА к плану: модуль core (KMP без UI, по плану #1), пакет org.easypaper.model. Шаг 1 (сейчас): core/src/commonMain/kotlin/org/easypaper/model/Schema.kt + commonTest/SchemaTest.kt — формат схемы v1 (CareRequest, WidgetSpec x7, Entry/EntryPayload x7, PatientRecord, EasyPaperJson; время = epoch millis Long, startDate = ISO-строка, без kotlinx-datetime). Gradle-файлы #1 НЕ трогаю: core нужен плагин kotlin serialization + kotlinx-serialization-json в commonMain. Шаг 2 (после каркаса и согласования dev.whyoleg.cryptography с mykhailo): storage/ RecordStore + EncryptedRecordStore AES-256-GCM + BlobStore/KeyProvider actual. Тесты шага 1 прогнаны во временном JVM-проекте вне репо: 5/5 зелёные.","review_notes":null,"status":"running","submitter":"vlad","title":"Модель виджетов и данных в commonMain: схема запроса врача (список виджетов: опросник, давление, вода, еда, лекарства, дневник, вопросы врачу), ответы, зашифрованное локальное хранилище; формат схемы зафиксировать первым коммитом [JB][IMC]","updated":"2026-11-21T15:25:27+00:00"}}','2026-11-21T15:25:27+00:00');
